create database GIScript character set utf8mb4 collate utf8mb4_general_ci;
use GIScript;

create table users (
	id int auto_increment primary key,
    nickname varchar(50) not null,
    password varchar(255) not null,
    email varchar(120) not null,
    avatar varchar(255) default null,
    country varchar(50),
    role enum('user', 'admin') default 'user',
    
unique (email)
);

create table category (
	id int auto_increment primary key,
	name varchar(150) not null,
    icon_class varchar(100) not null
);


create table favorites (
	id int auto_increment primary key,
    user_id int not null,
    icon_id int not null,
	created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

    unique(user_id, icon_id),
foreign key (user_id) references users(id) on delete cascade,
foreign key (icon_id) references icon(id) on delete cascade
);

create table if not exists icon (
	id int auto_increment primary key,
    name varchar(100) not null,
	icon_class varchar(150),
	svg_path text,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, 
    
    category_id int not null,
foreign key (category_id) references category(id) on delete cascade
);

create table if not exists ratings (
	id int auto_increment primary key,
	user_id int not null,
    icon_id int not null,
    rating tinyint not null check (rating in (1, -1)), -- 1 = лайк, -1 = дизлайк
	created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, 

	unique unique_user_icon_rating (user_id, icon_id),

foreign key (user_id) references users(id) on delete cascade,
foreign key (icon_id) references icon(id) on delete cascade
);



